const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  try {
    // 1. Geometry & Time Definitions
    const line = ee.Geometry.LineString([[-90.09, 35.155], [-90.04, 35.155]]); // E-W transect across Mississippi near Memphis
    const roi = line.buffer(2000);
    const periods = [
      {label: '2021-09', start: '2021-09-01', end: '2021-10-01'},
      {label: '2023-09', start: '2023-09-01', end: '2023-10-01'}
    ];
    const ndwiThresh = 0.1;

    // Helpers
    const ev = (obj) => new Promise((resolve, reject) => obj.evaluate(resolve, reject));
    const lineLenM = await ev(line.length(1));

    function maskS2(img) {
      const scl = img.select('SCL');
      const cloudFree = scl.neq(3).and(scl.neq(8)).and(scl.neq(9)).and(scl.neq(10)).and(scl.neq(11));
      return img.updateMask(cloudFree);
    }
    function s2Composite(start, end) {
      return ee.ImageCollection('COPERNICUS/S2_SR_HARMONIZED')
        .filterDate(start, end)
        .filterBounds(roi)
        .map(maskS2)
        .median();
    }
    function ndwiFromS2(img) {
      const g = img.select('B3').divide(10000);
      const n = img.select('B8').divide(10000);
      return g.subtract(n).divide(g.add(n)).rename('ndwi');
    }

    function maskLS(img) {
      const qa = img.select('QA_PIXEL');
      const mask = qa.bitwiseAnd(1 << 1).eq(0) // dilated cloud
        .and(qa.bitwiseAnd(1 << 2).eq(0))      // cirrus
        .and(qa.bitwiseAnd(1 << 3).eq(0))      // cloud
        .and(qa.bitwiseAnd(1 << 4).eq(0));     // cloud shadow
      return img.updateMask(mask);
    }
    function lsComposite(start, end) {
      const l8 = ee.ImageCollection('LANDSAT/LC08/C02/T1_L2').filterDate(start, end).filterBounds(roi).map(maskLS);
      const l9 = ee.ImageCollection('LANDSAT/LC09/C02/T1_L2').filterDate(start, end).filterBounds(roi).map(maskLS);
      return l8.merge(l9).median();
    }
    function ndwiFromLS(img) {
      const g = img.select('SR_B3').multiply(0.0000275).add(-0.2);
      const n = img.select('SR_B5').multiply(0.0000275).add(-0.2);
      return g.subtract(n).divide(g.add(n)).rename('ndwi');
    }
    async function datasetCounts(ndwiImg, scale) {
      const ones = ee.Image.constant(1).rename('ones').updateMask(ndwiImg.mask());
      const totalAll = ee.Image.constant(1).rename('ones');
      const total = await ev(totalAll.reduceRegion({reducer: ee.Reducer.count(), geometry: line, scale: scale, maxPixels: 1e9}).get('ones'));
      const valid = await ev(ones.reduceRegion({reducer: ee.Reducer.count(), geometry: line, scale: scale, maxPixels: 1e9}).get('ones'));
      const water = await ev(ndwiImg.updateMask(ndwiImg.gt(ndwiThresh))
        .reduceRegion({reducer: ee.Reducer.count(), geometry: line, scale: scale, maxPixels: 1e9}).get('ndwi'));
      const t = (total || 0), v = (valid || 0), w = (water || 0);
      return {total: t, valid: v, water: w, width_m: w * scale, cloud_pct: t > 0 ? (100 * (t - v) / t) : null};
    }
    async function processPeriod(p) {
      // Build collections and sizes
      const s2Col = ee.ImageCollection('COPERNICUS/S2_SR_HARMONIZED').filterDate(p.start, p.end).filterBounds(roi);
      const lsCol = ee.ImageCollection('LANDSAT/LC08/C02/T1_L2').filterDate(p.start, p.end).filterBounds(roi)
        .merge(ee.ImageCollection('LANDSAT/LC09/C02/T1_L2').filterDate(p.start, p.end).filterBounds(roi));
      const s2Size = await ev(s2Col.size());
      const lsSize = await ev(lsCol.size());
      let best = null;
      let chosen = null;

      if (s2Size > 0) {
        const s2 = s2Composite(p.start, p.end);
        const ndwiS2 = ndwiFromS2(s2);
        const s2stats = await datasetCounts(ndwiS2, 10);
        best = {dataset: 'S2', imgs: s2Size, ...s2stats};
        chosen = best.valid > 0 ? 'S2' : null;
      }
      if (lsSize > 0) {
        const ls = lsComposite(p.start, p.end);
        const ndwiLS = ndwiFromLS(ls);
        const lsstats = await datasetCounts(ndwiLS, 30);
        if (!best || lsstats.valid > (best.valid || 0)) {
          best = {dataset: 'L8/9', imgs: lsSize, ...lsstats};
          chosen = best.valid > 0 ? 'L8/9' : chosen || (best.valid > 0 ? 'L8/9' : null);
        }
      }

      return {
        label: p.label,
        s2Imgs: s2Size || 0,
        lImgs: lsSize || 0,
        result: best,
        chosen: chosen,
        status: (s2Size === 0 && lsSize === 0) ? 'C1' : (best && best.valid === 0 ? 'C2' : null)
      };
    }

    console.log(`Transect length (m): ${Math.round(lineLenM)}`);
    const r1 = await processPeriod(periods[0]);
    console.log(`${r1.label} Images -> S2: ${r1.s2Imgs}, L8/9: ${r1.lImgs}`);
    if (r1.status === 'C1') { console.log('C1'); return; }
    if (!r1.result || r1.status === 'C2') { console.log('C2'); return; }
    const w1 = r1.result.width_m;
    const cloud1 = r1.result.cloud_pct != null ? r1.result.cloud_pct.toFixed(1) : 'NA';
    console.log(`${r1.label} chosen: ${r1.result.dataset}; totalPts: ${r1.result.total}, valid: ${r1.result.valid}, cloud%: ${cloud1}, waterPts: ${r1.result.water}, width_m: ${Math.round(w1)}`);

    const r2 = await processPeriod(periods[1]);
    console.log(`${r2.label} Images -> S2: ${r2.s2Imgs}, L8/9: ${r2.lImgs}`);
    if (r2.status === 'C1') { console.log('C1'); return; }
    if (!r2.result || r2.status === 'C2') { console.log('C2'); return; }
    const w2 = r2.result.width_m;
    const cloud2 = r2.result.cloud_pct != null ? r2.result.cloud_pct.toFixed(1) : 'NA';
    console.log(`${r2.label} chosen: ${r2.result.dataset}; totalPts: ${r2.result.total}, valid: ${r2.result.valid}, cloud%: ${cloud2}, waterPts: ${r2.result.water}, width_m: ${Math.round(w2)}`);

    // Validation & Final Answer selection
    if ([w1, w2].some(v => v == null || isNaN(v) || v < 0 || v > lineLenM * 1.5)) {
      console.log('C3');
      return;
    }
    // Answer: Did width decrease in 2023 vs 2021?
    const decreased = w2 < w1;
    console.log(`Widths (m): 2021-09=${Math.round(w1)}, 2023-09=${Math.round(w2)}`);
    console.log(decreased ? 'A' : 'B');
  } catch (e) {
    console.log(`Error: ${e}`);
    console.log('D');
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE();
